import{_ as o,o as a,c as i,a0 as t}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /qa-resolve","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/qa-resolve.md","filePath":"references/skills/qa-resolve.md"}'),n={name:"references/skills/qa-resolve.md"};function l(c,e,r,s,d,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="skill-qa-resolve" tabindex="-1">Skill: <code>/qa-resolve</code> <a class="header-anchor" href="#skill-qa-resolve" aria-label="Permalink to &quot;Skill: `/qa-resolve`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>qa-resolve</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/qa-resolve &lt;qa-id&gt;</code></li><li>Kèm theo câu trả lời/giải pháp từ User (nếu có): <ul><li>Ví dụ: <code>/qa-resolve QA-cmp-adm-002-02-01-02-0001 \\n Giữ copy legacy cho title.</code></li></ul></li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>ID của file QA Tech Debt (ví dụ: <code>QA-cmp-adm-002-02-01-02-0001.yaml</code>) nằm trong <code>qa/open/</code>.</li><li>Lời giải (Solution) do User cung cấp qua Prompt.</li><li>File đích (<code>target.path</code>) và con trỏ JSON/YAML (<code>target.at</code>) được khai báo bên trong file QA.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>File đích (<code>*.bundle.yaml</code> hoặc <code>01-backend-spec.yaml</code>) được điền giải pháp vào đúng vị trí <code>target.at</code> (thay thế <code>#missing_info</code>).</li><li>Xóa bỏ ID này khỏi mảng <code>pendingTechDebt</code> hoặc các tag <code>#tech-debt:QA-...</code>.</li><li>XÓA BỎ hoàn toàn file <code>qa/open/&lt;id&gt;.yaml</code> khỏi hệ thống (Đóng QA thành công).</li><li><code>flowgrid split</code> chạy lại để làm mới dữ liệu IR.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Chuyên dùng để đóng các khoản nợ kỹ thuật (Tech Debt) hoặc các khoảng trống (Gaps) nghiệp vụ đã được ghi nhận trước đó từ các form AskQuestion.</li><li>Quá trình này <strong>đơn nhiệm</strong> (chỉ giải quyết 1 QA ID mỗi lần gọi) để đảm bảo độ chính xác tuyệt đối.</li><li>Agent phải đọc <code>target.path</code> từ file QA để biết chính xác cần vá file nào, không được tự ý phỏng đoán (guesswork) vị trí sửa.</li><li>Nếu đích sửa đổi là file <code>01-backend-spec.yaml</code>, Agent cần gọi tiếp <code>flowgrid openapi_gen --spec &lt;01&gt;</code> để cập nhật lại swagger.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Nhận đầu vào do các skill <code>grill-*</code> (bqa, dev, docs) tạo ra qua tuỳ chọn &quot;Log as Tech Debt&quot;.</li><li><strong>Sau đó:</strong> Nếu sau khi điền xong mà vẫn thiếu cấu hình gen (VD: <code>codegen.profile</code>), gọi tiếp <code>/grill-dev</code> hoặc <code>/grill-api-spec</code>.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Luật AskQuestion Tech Debt:</strong> Nếu User gọi lệnh <code>/qa-resolve &lt;qa-id&gt;</code> nhưng <strong>KHÔNG</strong> ghi kèm theo giải pháp (Solution) =&gt; Agent bắt buộc phải bật Form AskQuestion hỏi User. Form phải có Option <code>&quot;Log as Tech Debt&quot;</code> (mặc dù đang ở trong tiến trình resolve) và các option gợi ý (Recommended).</li><li>Tuyệt đối không tạo ra thuộc tính <code>openQuestions</code> hoặc <code>bundle.spec.api</code> trên các file YAML. Mọi thắc mắc đều phải được tracking dưới dạng file vật lý trong <code>qa/open/</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/qa-resolve</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const p=o(n,[["render",l]]);export{g as __pageData,p as default};
